    표8_상담적용: [
        {"상황":"모든 것을 자기 힘으로 이루었다고 자부하는 분", "성경원리":"파라오가 '내 강은 내 것이라 내가 만들었다'고 했으나 하나님의 심판을 받았다", "실제적용":"신 8:17-18을 묵상하라. '내 능력으로 이 재물을 얻었다 하지 말라 재물 얻을 능력을 네게 주시는 이는 하나님이시다'"},
        {"상황":"하나님이 주신 것을 자기 것으로 착각하는 분", "성경원리":"'내 강은 내 것'이라는 선언이 교만의 핵심이었다. 모든 것은 하나님의 것이다", "실제적용":"대상 29:14 '모든 것이 주에게서 왔사오니 우리가 주의 손에서 받은 것으로 드렸을 뿐'. 가진 것에 감사하되 자기 것으로 착각하지 말라"},
        {"상황":"자기 영역에서 절대적으로 군림하려는 분", "성경원리":"파라오가 나일강의 악어처럼 자기 영역에서 군림했으나 하나님이 대적하셨다", "실제적용":"자기 영역(가정, 직장, 사역)에서 독재자가 되지 말라. 하나님이 참된 주인이시다. 겸손한 청지기가 되라"}
    ],
    표9_교차참조: [
        {"구절":"사 51:9", "연결점":"라합을 쳐서 조각내시며 용을 찌르신 분이 아니시냐", "구분":"구약"},
        {"구절":"시 74:13-14", "연결점":"바다 가운데에서 용들의 머리를 깨뜨리셨으며", "구분":"구약"},
        {"구절":"시 24:1", "연결점":"땅과 거기에 충만한 것이 다 여호와의 것이로다", "구분":"구약"},
        {"구절":"시 100:3", "연결점":"그가 우리를 만드셨고 우리는 그의 것이라", "구분":"구약"},
        {"구절":"신 8:17-18", "연결점":"내 능력으로 이 재물을 얻었다 말하지 말라", "구분":"구약"},
        {"구절":"계 12:3-9", "연결점":"큰 붉은 용 - 사탄의 상징", "구분":"신약"},
        {"구절":"계 20:2", "연결점":"용을 잡으니 곧 옛 뱀이요 마귀요 사탄이라", "구분":"신약"},
        {"구절":"약 4:6", "연결점":"하나님이 교만한 자를 대적하시고 겸손한 자에게 은혜를 주신다", "구분":"신약"}
    ]
