    표8_상담적용: [
        {"상황":"자기가 의지하던 자원이 고갈된 분", "성경원리":"이집트가 의지하던 나일강이 마르듯, 세상의 자원은 고갈될 수 있다", "실제적용":"마르지 않는 생명수의 원천이신 그리스도를 의지하라. 요 4:14 '내가 주는 물을 마시는 자는 영원히 목마르지 아니하리니'"},
        {"상황":"하나님의 보호가 철회된 것 같은 분", "성경원리":"이집트가 '악한 자의 손에 팔린' 것은 하나님의 보호 철회의 결과였다", "실제적용":"하나님이 보호를 철회하신 것 같은 상황에서도 회개하고 돌아오면 보호가 회복된다. 대하 7:14 '내 이름으로 일컫는 백성이 겸손하면 내가 들으리라'"},
        {"상황":"하나님의 말씀을 의심하는 분", "성경원리":"'나 여호와가 말하였다'는 하나님의 이름으로 보증된 절대적 확실성이다", "실제적용":"민 23:19 '하나님은 사람이 아니시니 거짓말을 하지 않으시고'. 하나님의 말씀의 확실성을 신뢰하라"}
    ],
    표9_교차참조: [
        {"구절":"겔 29:3", "연결점":"내 강은 내 것이라 내가 만들었다 - 이제 그 강이 마른다", "구분":"구약"},
        {"구절":"사 19:5-7", "연결점":"나일강이 마르고 갈대가 시들 것", "구분":"구약"},
        {"구절":"삿 2:14", "연결점":"여호와께서 이스라엘을 노략하는 자의 손에 파시매", "구분":"구약"},
        {"구절":"민 23:19", "연결점":"하나님은 사람이 아니시니 거짓말을 하지 않으시고", "구분":"구약"},
        {"구절":"요 4:14", "연결점":"내가 주는 물을 마시는 자는 영원히 목마르지 아니하리니", "구분":"신약"},
        {"구절":"요 7:38", "연결점":"나를 믿는 자는 생수의 강이 흘러나오리라", "구분":"신약"},
        {"구절":"계 22:1", "연결점":"생명수의 강이 하나님과 어린 양의 보좌로부터 나와서", "구분":"신약"},
        {"구절":"고후 1:20", "연결점":"하나님의 약속은 다 그리스도 안에서 예와 아멘이라", "구분":"신약"}
    ]
